  "api_surface": [
    {
      "name": "ToolNode",
      "signature": "pub struct ToolNode { pub turn_index: usize, pub tool_name: CompactString, pub target_symbol: Option<CompactString>, pub target_file: Option<CompactString>, pub is_mutation: bool, pub had_error: bool }",
      "description": "A single tool invocation node in the trajectory graph, carrying the grounded target file/symbol used for cycle and grounding-score analysis.",
      "error_conditions": []
    },
    {
      "name": "CircularLoopAnomaly",
      "signature": "pub struct CircularLoopAnomaly { pub symbol: CompactString, pub cycle_depth: usize }",
