    "Hook process interception or daemon async scheduling (handled by lumen-daemon).",
    "Log file parsing or stream transformation (handled by lumen-session).",
    "Direct network I/O or remote cloud sync.",
    "Ownership of the Mac app's read-model schema: any Swift/Mac client, if/when built, is a consumer of schemas/read-contracts/v1.schema.json, not its source of truth.",
    "Category-score computation and discovered-category clustering (handled by lumen-insights, not yet integrated into any daemon transaction)."
  ],
  "api_surface": [
    {
      "name": "SqliteStore",
      "signature": "pub struct SqliteStore { pool: r2d2::Pool<r2d2_sqlite::SqliteConnectionManager>, is_read_only: bool }; impl SqliteStore { pub fn open(path: &Utf8Path) -> Result<Self, StoreError>; pub fn open_read_only(path: &Utf8Path) -> Result<Self, StoreError>; pub fn run_migrations(&self) -> Result<usize, StoreError>; pub fn connection(&self) -> Result<r2d2::PooledConnection<r2d2_sqlite::SqliteConnectionManager>, StoreError>; }",
      "description": "Connection pool manager configuring SQLite in WAL mode with PRAGMA foreign_keys = ON and query_only flags for concurrent multi-reader access.",
      "error_conditions": [
        "StoreError::MigrationFailed if forward schema migration encounters SQL error",
        "StoreError::ReadOnlyViolation if write query is attempted on read-only pool"
      ]
    },
    {
      "name": "QueueRepository",
      "signature": "pub struct QueueRepository<'a> { conn: &'a rusqlite::Connection }; impl<'a> QueueRepository<'a> { pub fn enqueue(&self, provider: &str, session_id: &str, source_path: &str, source_hash: u64) -> Result<i64, StoreError>; pub fn fetch_pending(&self, limit: usize) -> Result<Vec<QueuedSessionRow>, StoreError>; pub fn mark_completed(&self, id: i64) -> Result<(), StoreError>; pub fn mark_failed(&self, id: i64, error: &str) -> Result<(), StoreError>; }",
      "description": "Repository managing the ingestion_queue table with exponential retry scheduling and dead-letter classification after 3 failures.",
      "error_conditions": []
    },
    {
      "name": "SessionRepository",
      "signature": "pub struct SessionRepository<'a> { conn: &'a rusqlite::Connection }; impl<'a> SessionRepository<'a> { pub fn upsert_session(&self, record: &SessionFactRecord) -> Result<(), StoreError>; pub fn get_session(&self, id: &str) -> Result<Option<SessionDetailReadModel>, StoreError>; pub fn list_recent(&self, filter: &SessionFilter) -> Result<Vec<SessionSummaryReadModel>, StoreError>; }",
      "description": "Repository for normalized session facts, supporting idempotent upserts keyed on (provider, provider_session_id) and typed read models.",
      "error_conditions": []
    },
    {
      "name": "FindingsRepository",
      "signature": "pub struct FindingsRepository<'a> { conn: &'a rusqlite::Connection }; impl<'a> FindingsRepository<'a> { pub fn insert_findings(&self, session_id: &str, findings: &[FindingFactRecord]) -> Result<(), StoreError>; pub fn list_top_findings(&self, limit: usize) -> Result<Vec<FindingReadModel>, StoreError>; }",
      "description": "Repository storing structured findings with confidence scores, evidence JSON payloads, and rule versions.",
      "error_conditions": []
    },
    {
      "name": "ToolCallRepository",
      "signature": "pub struct ToolCallRepository<'a> { conn: &'a rusqlite::Connection }; impl<'a> ToolCallRepository<'a> { pub fn new(conn: &'a rusqlite::Connection) -> Self; pub fn insert_tool_calls(&self, session_id: i64, calls: &[ToolCallFactRecord]) -> Result<(), StoreError>; pub fn list_by_session(&self, session_id: i64) -> Result<Vec<ToolCallReadModel>, StoreError>; pub fn tool_counts_by_session(&self, session_id: i64) -> Result<BTreeMap<CompactString, usize>, StoreError>; pub fn error_counts_by_session(&self, session_id: i64) -> Result<BTreeMap<CompactString, usize>, StoreError>; }",
      "description": "Repository for the tool_calls table (id, session_id, turn_index, tool_name, call_id, intent_kind, is_error, latency_ms). insert_tool_calls batch-inserts ToolCallFactRecord rows for a session using a single prepared statement in a loop, following FindingsRepository::insert_findings's pattern; an empty slice inserts zero rows without error. tool_counts_by_session and error_counts_by_session are the methods SessionRepository::get_session uses to populate SessionDetailReadModel's tool_counts/error_counts fields (previously hardcoded to BTreeMap::new()).",
      "error_conditions": []
    },
    {
      "name": "RollupRepository",
      "signature": "pub struct RollupRepository<'a> { conn: &'a rusqlite::Connection }; impl<'a> RollupRepository<'a> { pub fn new(conn: &'a rusqlite::Connection) -> Self; pub fn upsert_rollup(&self, record: &RollupFactRecord) -> Result<(), StoreError>; pub fn get_rollup(&self, period_start: chrono::DateTime<chrono::Utc>, period_type: &str) -> Result<Option<RollupReadModel>, StoreError>; pub fn list_rollups(&self, period_type: &str, limit: usize) -> Result<Vec<RollupReadModel>, StoreError>; }",
      "description": "Repository for the rollups table (id, period_start, period_type, session_count, total_cost_usd, total_savings_usd, total_duration_ms). upsert_rollup's idempotent ON CONFLICT requires a UNIQUE(period_start, period_type) index, which does not exist on the rollups table created by migration V5 (SQLite has no ALTER TABLE ADD CONSTRAINT) — this SHALL be added via a new, separate migration (V6: CREATE UNIQUE INDEX IF NOT EXISTS ux_rollups_period ON rollups(period_start, period_type)), never by editing the already-applied V5 migration in place.",
      "error_conditions": []
    },
    {
      "name": "CommandEventRepository",
      "signature": "pub struct CommandEventRepository<'a> { conn: &'a rusqlite::Connection }; impl<'a> CommandEventRepository<'a> { pub fn new(conn: &'a rusqlite::Connection) -> Self; pub fn insert_command_events(&self, session_id: &str, events: &[CommandEventFactRecord]) -> Result<(), StoreError>; pub fn list_by_session(&self, session_id: &str) -> Result<Vec<CommandEventReadModel>, StoreError>; }",
      "description": "Repository for the command_events table. insert_command_events persists command_base and redacted argument patterns per CRIT-LUMEN-037's redaction requirement, ensuring zero raw private arguments are written.",
      "error_conditions": []
    },
    {
      "name": "SnapshotRepository",
      "signature": "pub struct SnapshotRepository<'a> { conn: &'a rusqlite::Connection }; impl<'a> SnapshotRepository<'a> { pub fn new(conn: &'a rusqlite::Connection) -> Self; pub fn save_snapshot(&self, provider: &str, session_id: &str, data: &[u8]) -> Result<i64, StoreError>; pub fn get_latest_snapshot(&self, provider: &str, session_id: &str) -> Result<Option<Vec<u8>>, StoreError>; }",
      "description": "Repository for the session_snapshots table (created by migration V1 per CRIT-LUMEN-032 but previously unimplemented). Used by lumen-daemon's PreCompact hook handler to persist pre-compaction transcript BLOBs.",
      "error_conditions": [
        "StoreError::WriteFailed if the BLOB insert fails or exceeds configured size limits"
