      "description": "Repository for the token_usage table (created by migration V1 per CRIT-LUMEN-032). insert_token_usage inserts one row per entry in TokenEconomics.per_model (keyed by model name, using ModelTokenSummary's input_tokens/output_tokens/cache_creation_tokens/cache_read_tokens/cost_usd/turns fields directly) rather than an invented intermediate record type.",
      "error_conditions": []
    },
    {
      "name": "ReadContractEnvelope",
      "signature": "pub struct ReadContractEnvelope<T: Serialize> { pub contract_version: &'static str, pub data: T }",
      "description": "Serialization wrapper applied at the CLI/API boundary to SessionSummaryReadModel, SessionDetailReadModel, FindingReadModel, ToolCallReadModel, and RollupReadModel, carrying the versioned read-contract identifier consumed by any external client.",
      "error_conditions": []
    }
  ],
  "acceptance_criteria": [
    {
      "id": "CRIT-LUMEN-030",
      "criterion": "WHEN SqliteStore opens a database file, THE SYSTEM SHALL configure PRAGMA journal_mode = WAL and PRAGMA foreign_keys = ON.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-031",
      "criterion": "WHEN open_read_only is called, THE SYSTEM SHALL configure PRAGMA query_only = ON and disallow any INSERT, UPDATE, or DELETE operations.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-032",
      "criterion": "WHEN migrations are executed on a fresh database, THE SYSTEM SHALL apply all migrations from V1 to V5 and create ingestion_queue, session_snapshots, pipeline_runs, sessions, tool_calls, command_events, token_usage, session_category_scores, findings, rollups, and discovered_categories tables.",
      "is_error_case": false,
      "judgment_call": false
    },
