      "id": "CRIT-LUMEN-033",
      "criterion": "WHEN upsert_session is called multiple times with identical (provider, provider_session_id), THE SYSTEM SHALL perform an idempotent update without creating duplicate rows.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-034",
      "criterion": "WHEN mark_failed is invoked on an ingestion queue item whose retry_count reaches 3, THE SYSTEM SHALL transition its status to 'dead_letter' and record the last error string.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-035",
      "criterion": "IF a database migration script fails during execution, THE SYSTEM SHALL roll back the transaction and return StoreError::MigrationFailed without modifying database state.",
      "is_error_case": true,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-036",
      "criterion": "WHEN list_recent is executed with limit = 50, THE SYSTEM SHALL return typed SessionSummaryReadModel structs in under 2 milliseconds.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-037",
      "criterion": "WHEN command events are inserted, THE SYSTEM SHALL store command_base and redacted argument patterns, ensuring zero raw private arguments are persisted.",
      "is_error_case": false,
      "judgment_call": false
    },
