1	use chrono::{DateTime, Utc};
2	use compact_str::CompactString;
3	use lumen_model::*;
4	use smallvec::SmallVec;
5	use std::io::BufRead;
6	
7	use crate::adapter::{AdapterCapabilities, IngestionError, SessionAdapter};
8	use crate::fingerprint::detect_orchestrator;
9	
10	pub struct ClaudeCodeAdapter;
11	
12	impl SessionAdapter for ClaudeCodeAdapter {
13	    fn name(&self) -> &'static str {
14	        "claude-code"
15	    }
16	
17	    fn matches_fingerprint(&self, sample: &str) -> bool {
18	        // Delegates to detect_orchestrator (the single source of truth for orchestrator
19	        // precedence) instead of maintaining an independently-coded condition that can drift.
20	        detect_orchestrator(sample.as_bytes()) == Some(OrchestratorKind::ClaudeCode)
21	    }
22	
23	    fn capabilities(&self) -> AdapterCapabilities {
24	        AdapterCapabilities {
25	            has_token_usage: true,
26	            has_tool_results: true,
27	            has_shell_commands: true,
28	            has_file_events: true,
29	            has_lifecycle_hooks: true,
30	            supports_incremental_offsets: true,
31	            supports_cost_estimation: true,
32	        }
33	    }
34	
35	    fn parse_stream<'a>(&self, reader: Box<dyn BufRead + 'a>) -> Result<CanonicalTranscript, IngestionError> {
36	        let mut session_id = CompactString::new("unknown");
37	        let mut model_family = CompactString::new("claude-3-5-sonnet-20241022");
38	        let mut turns = Vec::new();
39	        let mut started_at = Utc::now();
40	        let mut ended_at = Utc::now();
41	        let mut has_start = false;
42	
43	        let mut total_input: u64 = 0;
44	        let mut total_output: u64 = 0;
45	        let mut total_cache_creation: u64 = 0;
46	        let mut total_cache_read: u64 = 0;
47	        let mut parse_failures: SmallVec<[ParseFailureRecord; 2]> = SmallVec::new();
48	        let mut otel_conversation_id: Option<CompactString> = None;
49	
50	        'lines: for (idx, line_res) in reader.lines().enumerate() {
51	            let line = match line_res {
52	                Ok(l) => l,
53	                Err(e) => return Err(IngestionError::Io(e)),
54	            };
55	
56	            let trimmed = line.trim();
57	            let clean_line = trimmed.strip_prefix('\u{FEFF}').unwrap_or(trimmed).trim();
58	            if clean_line.is_empty() {
59	                continue;
60	            }
61	
62	            let val: serde_json::Value = match serde_json::from_str(clean_line) {
63	                Ok(v) => v,
64	                Err(e) => {
