326	impl ClaudeCodeAdapter {
327	    /// Parses a session's main transcript file plus any sibling `subagents/<worker>.jsonl`
328	    /// files found alongside it, linking each as a child transcript via `parent_session_id`
329	    /// and `subagent_role` (CRIT-LUMEN-026). A missing `subagents/` directory, or a
330	    /// `subagents/<worker>.jsonl` file with no corresponding `is_sidechain` entries in the
331	    /// main file, is not an error -- it is simply linked (or, for a missing directory, simply
332	    /// absent) without failing the parse.
333	    pub fn parse_session_with_subagents(
334	        &self,
335	        session_dir: &std::path::Path,
336	        main_file_name: &str,
337	    ) -> Result<CanonicalTranscript, IngestionError> {
338	        let main_path = session_dir.join(main_file_name);
339	        let main_file = std::fs::File::open(&main_path).map_err(IngestionError::Io)?;
340	        let mut transcript = self.parse_stream(Box::new(std::io::BufReader::new(main_file)))?;
341	
342	        let subagents_dir = session_dir.join("subagents");
343	        if let Ok(entries) = std::fs::read_dir(&subagents_dir) {
344	            for entry in entries.flatten() {
345	                let path = entry.path();
346	                if path.extension().and_then(|e| e.to_str()) != Some("jsonl") {
347	                    continue;
348	                }
349	                let worker = path.file_stem().and_then(|s| s.to_str()).unwrap_or("unknown").to_string();
350	                let file = std::fs::File::open(&path).map_err(IngestionError::Io)?;
351	                let mut child = self.parse_stream(Box::new(std::io::BufReader::new(file)))?;
352	                child.parent_session_id = Some(transcript.session_id.clone());
353	                child.subagent_role = Some(CompactString::new(worker));
354	                transcript.subagents.push(child);
355	            }
356	        }
357	
358	        Ok(transcript)
359	    }
360	}
361	
362	fn parse_tool_intent(name: &str, input: &serde_json::Value) -> ToolIntent {
363	    match name {
364	        "view_file" | "Read" | "read_file" => {
365	            let path =
366	                input.get("AbsolutePath").or_else(|| input.get("file_path")).and_then(|v| v.as_str()).unwrap_or("");
367	            ToolIntent::FileRead { path: CompactString::new(path), line_range: None }
368	        }
369	        "replace_file_content" | "Edit" | "edit_file" => {
370	            let path =
371	                input.get("TargetFile").or_else(|| input.get("file_path")).and_then(|v| v.as_str()).unwrap_or("");
372	            ToolIntent::FileEdit { path: CompactString::new(path), lines_added: 0, lines_removed: 0 }
373	        }
374	        "write_to_file" | "Write" => {
375	            let path =
376	                input.get("TargetFile").or_else(|| input.get("file_path")).and_then(|v| v.as_str()).unwrap_or("");
377	            ToolIntent::FileCreate { path: CompactString::new(path) }
378	        }
379	        "grep_search" | "rg" => {
380	            let q = input.get("Query").or_else(|| input.get("pattern")).and_then(|v| v.as_str()).unwrap_or("");
381	            ToolIntent::CodeSearch { tool: CompactString::new(name), query: CompactString::new(q), is_ast: false }
382	        }
383	        "find_by_name" | "fd" => {
384	            let p = input.get("Pattern").and_then(|v| v.as_str()).unwrap_or("");
385	            ToolIntent::FileDiscovery { tool: CompactString::new(name), pattern: CompactString::new(p) }
386	        }
387	        "run_command" | "Bash" | "bash" => {
388	            let cmd = input.get("CommandLine").or_else(|| input.get("command")).and_then(|v| v.as_str()).unwrap_or("");
389	            if cmd.starts_with("git") {
390	                ToolIntent::VersionControl { action: CompactString::new(cmd) }
391	            } else if cmd.contains("test") {
392	                ToolIntent::TestExecution { runner: CompactString::new("shell"), target_suite: None }
393	            } else {
394	                ToolIntent::Other { raw_name: CompactString::new(name) }
395	            }
396	        }
397	        _ => ToolIntent::Other { raw_name: CompactString::new(name) },
398	    }
399	}
