113	    /// Normalizes a raw, provider-versioned model string (e.g. "claude-3-5-haiku-20241022",
114	    /// "gpt-4o-2024-08-06", "gemini-2.0-flash-001") down to one of this table's seeded
115	    /// canonical keys, by trying progressively shorter '-'-delimited prefixes of `model`
116	    /// against the set of model names actually present in `self.rates`, longest prefix first.
117	    /// Returns `None` when no prefix matches any seeded key -- callers must fall back to the
118	    /// CRIT-LUMEN-008 unrecognized-model behavior in that case.
119	    ///
120	    /// A small explicit alias table was considered instead, but seeded keys are themselves
121	    /// hyphen-delimited words (e.g. "claude-3-5-haiku") and every real-world date/version
122	    /// suffix observed (YYYYMMDD, YYYY-MM-DD, "-001", "-exp", "-32b-instruct") is just extra
123	    /// hyphen-delimited segments appended after the canonical name. Prefix-shortening solves
124	    /// all of them with one algorithm and needs no maintenance as new dated releases appear,
125	    /// whereas an alias table would need a new entry per new version string.
126	    fn normalize_model_key<'a>(&'a self, model: &'a str) -> Option<&'a str> {
127	        let parts: Vec<&str> = model.split('-').collect();
128	        for end in (1..=parts.len()).rev() {
129	            let candidate = &model[..Self::prefix_byte_len(&parts, end)];
130	            if self.rates.iter().any(|r| r.model == candidate) {
131	                return Some(candidate);
132	            }
133	        }
134	        None
135	    }
136	
137	    /// Byte length of the '-'-joined prefix consisting of the first `count` elements of
138	    /// `parts` (which were produced by splitting the original string on '-').
139	    fn prefix_byte_len(parts: &[&str], count: usize) -> usize {
140	        let joined_len: usize = parts[..count].iter().map(|p| p.len()).sum();
141	        // account for the (count - 1) '-' separators between the included parts
142	        joined_len + count.saturating_sub(1)
143	    }
144	
145	    /// Looks up the rate for (model, tier, kind) whose effective window contains `as_of`.
146	    /// Falls back to `claude-3-5-sonnet`'s rate for the requested kind when the model
147	    /// string -- after normalizing away any provider-versioning suffix -- matches no row at
148	    /// all (CRIT-LUMEN-008). When the model IS recognized (matches at least one row, possibly
149	    /// only after normalization) but has no row for this specific (tier, kind, as_of), returns
150	    /// 0.0 directly rather than substituting another model's rate (CRIT-LUMEN-161).
151	    ///
152	    /// When a specific `tier` is requested but `lookup_model` has no row matching that exact
153	    /// tier for this (kind, as_of), falls back to `lookup_model`'s own `tier: None` row for the
154	    /// same (kind, as_of) before giving up (Blocker #2). seed() pushes every row with
155	    /// `tier: None`, so without this fallback any caller that passes a real tier (e.g.
156	    /// CodexAdapter's captured `service_tier`) matched zero rows and silently priced at 0.0. A
157	    /// row that matches the exact requested tier still always wins over this fallback.
158	    pub fn rate_for(&self, model: &str, tier: Option<&str>, kind: TokenRateKind, as_of: DateTime<Utc>) -> f64 {
159	        let normalized = self.normalize_model_key(model);
160	        let lookup_model = normalized.unwrap_or("claude-3-5-sonnet");
161	
162	        let matching = |wanted_tier: Option<&str>| {
163	            self.rates
164	                .iter()
165	                .filter(|r| {
166	                    r.model == lookup_model
167	                        && r.kind == kind
168	                        && r.tier.as_deref() == wanted_tier
169	                        && r.effective_from <= as_of
170	                        && r.effective_until.is_none_or(|until| as_of < until)
171	                })
172	                .max_by_key(|r| r.effective_from)
173	                .map(|r| r.rate_per_m)
174	        };
175	
176	        matching(tier).or_else(|| if tier.is_some() { matching(None) } else { None }).unwrap_or(0.0)
177	    }
178	}
